const MONTHS: Record<string, string> = {
  enero: "01", febrero: "02", marzo: "03", abril: "04", mayo: "05", junio: "06",
  julio: "07", agosto: "08", septiembre: "09", octubre: "10", noviembre: "11", diciembre: "12",
};

// Convierte "21 de septiembre" en "2026-09-21" para los buscadores.
export function isoDate(post: Post, year = 2026) {
  const [day, , month] = post.date.split(" ");
  return `${year}-${MONTHS[month]}-${day.padStart(2, "0")}`;
}

export function getPost(slug: string) {
  return posts.find((p) => p.slug === slug);
}

export function readingMinutes(post: Post) {
  const words = post.body.join(" ").split(/\s+/).length;
  return Math.max(1, Math.round(words / 200));
}

export function seriesNeighbors(post: Post) {
  if (!post.series) return { prev: undefined, next: undefined };
  const inSeries = posts
    .filter((p) => p.series?.name === post.series!.name)
    .sort((a, b) => a.series!.part - b.series!.part);
  const i = inSeries.findIndex((p) => p.slug === post.slug);
  return { prev: inSeries[i - 1], next: inSeries[i + 1] };
}

export function dateNeighbors(post: Post) {
  const i = posts.findIndex((p) => p.slug === post.slug);
  return { newer: posts[i - 1], older: posts[i + 1] };
}
